CREATE TABLE design_files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), design_job_id UUID REFERENCES design_jobs(id), uploaded_by UUID REFERENCES users(id), original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL, mime_type VARCHAR(120) NOT NULL, file_size BIGINT NOT NULL CHECK(file_size>=0), version_no INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(50) NOT NULL, title VARCHAR(160) NOT NULL, message TEXT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE app_settings (key VARCHAR(100) PRIMARY KEY, value JSONB NOT NULL, updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX files_job_idx ON design_files(design_job_id,version_no DESC);CREATE INDEX notifications_user_idx ON notifications(user_id,is_read,created_at DESC);
CREATE TABLE portal_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id), token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
